from fractions import Fraction


def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    jump = {a: b for a, b in jumps}

    def resolve(x: int) -> int:
        while x in jump:
            x = jump[x]
        return x

    def next_cells(p: int) -> list[int]:
        cells = []
        for r in range(1, m + 1):
            q = p + r if p + r <= n else 2 * n - p - r
            cells.append(resolve(q))
        return cells

    # Explore states reachable from the start (cell 0); cell n is absorbing.
    trans = {}
    reachable = {0}
    stack = [0]
    while stack:
        p = stack.pop()
        trans[p] = next_cells(p)
        for q in trans[p]:
            if q != n and q not in reachable:
                reachable.add(q)
                stack.append(q)

    # Every reachable state must be able to reach n, otherwise the game may never end.
    can_end = set()
    changed = True
    while changed:
        changed = False
        for p in reachable:
            if p not in can_end and any(q == n or q in can_end for q in trans[p]):
                can_end.add(p)
                changed = True
    if len(can_end) != len(reachable):
        return None

    # E[s] = 1 + (1/m) * sum over rolls of E[next], with E[n] = 0.
    states = sorted(reachable)
    pos = {s: i for i, s in enumerate(states)}
    k = len(states)
    inv_m = Fraction(1, m)

    A = [[Fraction(0)] * (k + 1) for _ in range(k)]
    for s in states:
        i = pos[s]
        A[i][i] += 1
        A[i][k] = Fraction(1)
        for q in trans[s]:
            if q != n:
                A[i][pos[q]] -= inv_m

    # Gauss-Jordan elimination over exact fractions.
    for col in range(k):
        piv = next(r for r in range(col, k) if A[r][col] != 0)
        A[col], A[piv] = A[piv], A[col]
        pv = A[col][col]
        A[col] = [x / pv for x in A[col]]
        for r in range(k):
            if r != col and A[r][col] != 0:
                f = A[r][col]
                A[r] = [x - f * y for x, y in zip(A[r], A[col])]

    ans = A[pos[0]][k]
    return [ans.numerator, ans.denominator]
